import { Link } from 'react-router-dom';
import usePageMeta from '../functions/usePageMeta';
import useToTop from '../functions/useToTop';

const NotFoundPage = () => {
  useToTop();
  usePageMeta({
    title: 'Lapa nav atrasta',
    description: 'Meklētā lapa netika atrasta. Atgriezieties uz Tropiks AZ sākumlapu.',
    path: '/404',
  });

  return (
    <main className="not-found-page">
      <section className="main-page-title">
        <h1>
          404<br />
          <span>Lapa nav atrasta</span>
        </h1>
      </section>
      <p className="standart-margin align-center">
        Šī adrese neeksistē vai produkts vairs nav pieejams katalogā.
      </p>
      <Link to="/" className="button-link">
        Uz sākumu
      </Link>
    </main>
  );
};

export default NotFoundPage;
